export const CORE_ALGORITHMS = ALGORITHMS.filter(item => item.isCoreAlgorithm);

export const METHODS_BY_SLUG = ALGORITHMS.reduce((acc, item) => {
  acc[item.slug] = item;
  acc[item.id] = item;
  return acc;
}, {});

export function getMethod(slugOrId) {
  return METHODS_BY_SLUG[slugOrId] || null;
}

export function getMethodsByCategory(categoryId) {
  return ALGORITHMS.filter(item => item.category === categoryId);
}

export function getCoreAlgorithms() {
  return CORE_ALGORITHMS;
}

export default ALGORITHMS;

